# Generate MPFR reference values on the shared inputs in `../inputs/`.
#
# Each value is `mpfr_log1p` at 256 bits, round-to-nearest, rounded once to
# binary64. MPFR is called directly, rather than through `Base.log1p( ::BigFloat )`,
# which throws a `DomainError` below -1 before reaching MPFR; MPFR itself
# returns NaN there.

import JSON
import SHA
import Dates

const PRECISION = 256;

"""
	decode( v )

Decode a JSON value from a shared input file as a double.
"""
function decode( v )
	if v isa AbstractString
		v == "NaN" && return NaN;
		v == "Infinity" && return Inf;
		v == "-Infinity" && return -Inf;
		error( "unexpected string in inputs: $(v)" );
	end
	return Float64( v );
end

"""
	encode( x )

Encode a double as a JSON value, matching the shared input files.
"""
function encode( x::Float64 )
	isnan( x ) && return "\"NaN\"";
	x == Inf && return "\"Infinity\"";
	x == -Inf && return "\"-Infinity\"";
	return string( x ); # shortest round-trip decimal
end

"""
	reference( x )

Compute `log1p( x )` with MPFR at `PRECISION` bits, and round once to binary64.
"""
function reference( x::Float64 )
	setprecision( BigFloat, PRECISION ) do
		bx = BigFloat( x );
		z = BigFloat();
		ccall( (:mpfr_log1p, Base.MPFR.libmpfr), Int32, (Ref{BigFloat}, Ref{BigFloat}, Base.MPFR.MPFRRoundingMode), z, bx, Base.MPFR.MPFRRoundNearest );
		return Float64( z, RoundNearest );
	end
end

"""
	libc()

Return the C library's name and version.
"""
function libc()
	if Sys.islinux()
		v = unsafe_string( ccall( :gnu_get_libc_version, Cstring, () ) );
		return "glibc $(v)";
	end
	return nothing;
end

"""
	gen( name )

Read the shared input file `name`, and write the reference values to a file of the same name.
"""
function gen( name )
	inpath = joinpath( inputs, name );
	bytes = read( inpath );
	data = JSON.parse( String( copy( bytes ) ) );
	x = Float64[ decode( v ) for v in data["x"] ];
	y = Float64[ reference( v ) for v in x ];

	meta = Dict(
		"source" => "mpfr",
		"function" => "mpfr_log1p",
		"implementation" => "mpfr_log1p at $(PRECISION) bits, round-to-nearest, rounded once to binary64",
		"versions" => Dict( "julia" => string( VERSION ), "mpfr" => string( Base.MPFR.version() ) ),
		"platform" => Dict( "os" => lowercase( string( Sys.KERNEL ) ), "arch" => string( Sys.ARCH ), "compiler" => nothing, "libc" => libc() ),
		"generated" => Dates.format( Dates.now( Dates.UTC ), "yyyy-mm-ddTHH:MM:SSZ" ),
		"inputs" => bytes2hex( SHA.sha256( bytes ) ),
		"regime" => data["regime"]
	);

	outfile = open( joinpath( dir, name ), "w" );
	write( outfile, "{\"x\":[", join( encode.( x ), "," ), "],\"expected\":[", join( encode.( y ), "," ), "],\"meta\":", JSON.json( meta ), "}\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Shared inputs:
inputs = joinpath( dir, "..", "inputs" );

for name in sort( filter( f -> endswith( f, ".json" ), readdir( inputs ) ) )
	gen( name );
end
